mapper.select:
select

from patient_base_info


        AND has_died = #{hasDied}

    AND id in

        #{id}

select pbi.id patientId,pbi.name,pbi.gender,TIMESTAMPDIFF(YEAR, pbi.birthday, CURDATE()) AS age,pbi.mobile,pbi.medical_number medicalNumber,peio.patient_kind patientKind
from patient_base_info pbi left join patient_exp_info peio on pbi.id = peio.patient_id
where pbi.id = #{id}

SELECT CONVERT(SUBSTR(medical_number, 10, 6), UNSIGNED INTEGER) as medical_number
FROM patient_base_info
WHERE LENGTH(medical_number) = 15 AND LEFT(medical_number, 3) = #{clinNum}

SELECT count(id)
FROM patient_base_info

    AND crt_id IN (-666,-777)

        AND DATE_FORMAT(crt_time,'%Y-%m-%d') = #{query.currentDate}


        AND org_id = #{query.orgId}

SELECT pbi.id AS patientId, pbi.name AS patientName, pbi.mobile, pbi.gender, pbi.birthday, TIMESTAMPDIFF(YEAR, pbi.birthday, CURDATE()) AS age, pbi.origin_type AS originType, pbi.origin_id AS originId, po.name AS originChannel, pbi.crt_time AS registrationTime FROM patient_base_info pbi LEFT JOIN patient_origin po ON pbi.origin_type = po.origin_type AND pbi.origin_id = po.id
AND pbi.crt_id IN (-666,-777)
AND DATE_FORMAT(pbi.crt_time,'%Y-%m-%d') = #{query.currentDate}
AND pbi.org_id = #{query.orgId}
ORDER BY pbi.crt_time DESC

select p1.id, p1.name, p1.mobile, p1.gender, p1.medical_number AS medicalNumber, p1.crt_time AS crtTime from patient_base_info p1 INNER JOIN patient_base_info p2 ON p1.id = p2.origin_id and p2.origin_type = 2
AND p2.inservice = 1
AND p2.id = #{patientId}
